CREATE OR REPLACE FUNCTION public.camera_ai_review_human(p_review uuid, p_decision text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE new_id uuid;
BEGIN
  IF auth.uid() IS NULL OR public.current_app_role() IS NULL OR
     public.current_app_role() NOT IN ('officer','botanist','researcher') THEN RAISE EXCEPTION 'STAFF_REQUIRED' USING ERRCODE='42501'; END IF;
  IF p_decision IS NULL OR p_decision NOT IN ('confirmed','incorrect','uncertain') THEN RAISE EXCEPTION 'DECISION_INVALID'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.camera_ai_reviews WHERE id=p_review AND status='completed') THEN RAISE EXCEPTION 'REVIEW_NOT_COMPLETED'; END IF;
  INSERT INTO public.camera_ai_human_reviews(review_id,reviewer_id,decision) VALUES (p_review,auth.uid(),p_decision) RETURNING id INTO new_id;
  RETURN new_id;
END $function$
CREATE OR REPLACE FUNCTION public.enforce_alert_staff_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.alert_status IS NOT DISTINCT FROM OLD.alert_status THEN
    IF NEW.resolution_notes IS DISTINCT FROM OLD.resolution_notes THEN
      RAISE EXCEPTION 'Notes can only be changed while resolving an alert' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF (SELECT public.current_app_role()) IS NULL OR
     (SELECT public.current_app_role()) NOT IN ('officer','botanist','researcher') OR auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Active staff required' USING ERRCODE='42501';
  END IF;
  IF OLD.alert_status='open' AND NEW.alert_status='acknowledged' THEN
    IF NEW.resolution_notes IS DISTINCT FROM OLD.resolution_notes THEN
      RAISE EXCEPTION 'Notes require resolution' USING ERRCODE='23514';
    END IF;
    NEW.acknowledged_by := auth.uid();
    NEW.acknowledged_at := now();
    NEW.resolved_by := OLD.resolved_by;
    NEW.resolved_at := OLD.resolved_at;
  ELSIF OLD.alert_status='acknowledged' AND NEW.alert_status='resolved' THEN
    NEW.acknowledged_by := OLD.acknowledged_by;
    NEW.acknowledged_at := OLD.acknowledged_at;
    NEW.resolved_by := auth.uid();
    NEW.resolved_at := now();
  ELSE
    RAISE EXCEPTION 'Invalid alert state transition' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$function$
